# ---------------- 02 cleaning ----------------
save("02_cleaning.ipynb", [
md("# 02. Làm sạch dữ liệu, xử lý mất cân bằng, mã hóa và chuẩn hóa"),
code(HEAD + "\nfrom sklearn.model_selection import RepeatedStratifiedKFold, cross_validate, train_test_split\nfrom sklearn.linear_model import LogisticRegression\nfrom sklearn.ensemble import RandomForestClassifier\nfrom imblearn.pipeline import Pipeline as ImbPipeline\nfrom imblearn.over_sampling import SMOTE"),
code("raw = pd.read_csv(DATA / 'heart_raw.csv')\ndf = raw.copy()\nlog = []  # ghi lại từng quyết định xử lý"),
md("## 1. Quyết định làm sạch\n| # | Vấn đề | Cách xử lý | Lý do |\n|---|---|---|---|\n| 1 | 1 dòng trùng lặp | Xóa | Dòng lặp làm một bệnh nhân được đếm hai lần, có nguy cơ rơi vào cả train lẫn test |\n| 2 | `ca = 4` (5 dòng trong file gốc, còn 4 sau khi xóa dòng trùng) | Đặt NaN | Ngoài khoảng hợp lệ 0 đến 3 |\n| 3 | `thal = 0` (2 dòng) | Đặt NaN | Ngoài khoảng hợp lệ 1 đến 3 |\n| 4 | NaN sau bước 2, 3 | Điền trong Pipeline (median cho số, mode cho phân loại) | Fit imputer chỉ trên train để tránh rò rỉ dữ liệu |\n| 5 | Ngoại lai (IQR) | Giữ nguyên, thống kê bên dưới | Giá trị đều khả dĩ về y học, bộ dữ liệu nhỏ nên xóa sẽ mất thông tin |\n| 6 | Nhãn bị đảo | `HeartDisease = 1 - target` | Xem notebook 01 mục 5 |\n\n`chol` và `trestbps` không có giá trị 0 trong bản này (khác bộ Heart Failure 918 dòng), nên không cần xử lý mã 0."),
code("n0 = len(df)\ndf = df.drop_duplicates().reset_index(drop=True)\nlog.append(('Xóa dòng trùng', n0 - len(df)))\nbad_ca = (df.ca == 4); bad_thal = (df.thal == 0)\ndf.loc[bad_ca, 'ca'] = np.nan; df.loc[bad_thal, 'thal'] = np.nan\nlog += [('ca=4 -> NaN', int(bad_ca.sum())), ('thal=0 -> NaN', int(bad_thal.sum()))]\ndf[TARGET] = 1 - df['target']\ndf = df.drop(columns='target')\npd.DataFrame(log, columns=['Thao tác', 'Số dòng'])"),
md("### Bảng trước và sau khi làm sạch"),
code("before = pd.DataFrame({'Trước': [raw.shape[0], raw.duplicated().sum(), int((raw.ca==4).sum()+(raw.thal==0).sum()), raw.isna().sum().sum()],\n                       }, index=['Số dòng', 'Dòng trùng', 'Giá trị mã sai (ca=4, thal=0)', 'NaN'])\nafter = pd.Series([df.shape[0], df.duplicated().sum(), 0, int(df.isna().sum().sum())], index=before.index)\nbefore['Sau'] = after; before"),
md("### Ngoại lai theo quy tắc IQR (chỉ thống kê, không xóa)"),
code("rows = []\nfor c in ['age','trestbps','chol','thalach','oldpeak']:\n    q1, q3 = df[c].quantile([.25, .75]); i = q3 - q1\n    lo, hi = q1 - 1.5*i, q3 + 1.5*i\n    rows.append((c, round(lo,1), round(hi,1), int(((df[c] < lo) | (df[c] > hi)).sum()), df[c].min(), df[c].max()))\npd.DataFrame(rows, columns=['Cột','Ngưỡng dưới','Ngưỡng trên','Số ngoại lai','Min','Max'])"),
code("fig, ax = plt.subplots(1, 5, figsize=(15, 3.2))\nfor a, c in zip(ax, ['age','trestbps','chol','thalach','oldpeak']):\n    sns.boxplot(y=df[c], ax=a, color='#8ecae6'); a.set_title(VN[c], fontsize=9); a.set_ylabel('')\nplt.suptitle('Hình 2.1. Boxplot các biến số để kiểm tra ngoại lai', y=1.04)\nsavefig('fig_2_1_boxplot_ngoai_lai')"),
code("df.to_csv(DATA / 'heart_clean.csv', index=False)\nprint('Đã lưu data/heart_clean.csv', df.shape)"),
md("## 2. Kiểm tra mất cân bằng lớp"),
code("vc = df[TARGET].value_counts().sort_index(); pct = (vc / len(df) * 100).round(1)\nfig, ax = plt.subplots(figsize=(4.8, 3.6))\nb = ax.bar(['Không bệnh (0)', 'Có bệnh (1)'], vc.values, color=['#8ecae6', '#e76f51'])\nfor r, v, p in zip(b, vc.values, pct.values): ax.text(r.get_x()+r.get_width()/2, v+2, f'{v} ({p}%)', ha='center')\nax.set_ylabel('Số bệnh nhân'); ax.set_title('Hình 2.2. Tỷ lệ hai lớp'); ax.set_ylim(0, vc.max()*1.15)\nsavefig('fig_2_2_ty_le_lop')\nprint(pct.to_dict(), '| tỷ lệ lớp lớn/lớp nhỏ =', round(vc.max()/vc.min(), 2))"),
md("Tỷ lệ lớp gần cân bằng. Ta vẫn **so sánh thực nghiệm** ba cách: không xử lý, `class_weight='balanced'` và SMOTE. Đánh giá bằng cross-validation lặp 5 fold x 3 lần trên **tập train** (SMOTE nằm trong pipeline nên chỉ sinh mẫu trên fold train, không rò rỉ sang fold kiểm tra)."),
code("X, y = df[FEATURES], df[TARGET]\nX_train, X_test, y_train, y_test = train_test_split(X, y, test_size=0.2, stratify=y, random_state=RANDOM_STATE)\ncv = RepeatedStratifiedKFold(n_splits=5, n_repeats=3, random_state=RANDOM_STATE)\nscoring = ['accuracy', 'precision', 'recall', 'f1']\nres = []\nfor mname, mk in {'Logistic Regression': lambda cw: LogisticRegression(max_iter=2000, class_weight=cw),\n                  'Random Forest': lambda cw: RandomForestClassifier(n_estimators=300, class_weight=cw, random_state=RANDOM_STATE)}.items():\n    for strat in ['Không xử lý', 'class_weight', 'SMOTE']:\n        if strat == 'SMOTE':\n            pipe = ImbPipeline([('prep', make_preprocessor()), ('smote', SMOTE(random_state=RANDOM_STATE)), ('clf', mk(None))])\n        else:\n            pipe = Pipeline([('prep', make_preprocessor()), ('clf', mk('balanced' if strat == 'class_weight' else None))])\n        s = cross_validate(pipe, X_train, y_train, cv=cv, scoring=scoring, n_jobs=-1)\n        res.append({'Mô hình': mname, 'Cách xử lý': strat, **{k: round(s['test_'+k].mean(), 3) for k in scoring}})\nimb = pd.DataFrame(res); imb"),
code("imb.to_csv(ROOT / 'report' / 'bang_so_sanh_mat_can_bang.csv', index=False)\nfig, ax = plt.subplots(figsize=(7, 3.8))\nsns.barplot(data=imb, x='Mô hình', y='recall', hue='Cách xử lý', ax=ax, palette='Blues')\nax.set_ylim(0.6, 1); ax.set_ylabel('Recall (nhóm có bệnh)'); ax.set_title('Hình 2.3. Recall theo cách xử lý mất cân bằng (CV trên tập train)')\nsavefig('fig_2_3_so_sanh_mat_can_bang')"),
md("## 3. Mã hóa và chuẩn hóa thang đo\n- **Biến số** (`age, trestbps, chol, thalach, oldpeak, ca`): `StandardScaler`. Chọn chuẩn hóa z-score vì Logistic Regression (và SVM nếu dùng) nhạy với thang đo; `chol` (~200) và `oldpeak` (~1) chênh nhau hai bậc độ lớn.\n- **Biến phân loại không có thứ tự** (`cp, restecg, slope, thal`): `OneHotEncoder`, để mô hình không hiểu nhầm mã 0,1,2,3 là có thứ tự.\n- **Biến nhị phân** (`sex, fbs, exang`): giữ nguyên 0/1.\n- Toàn bộ nằm trong `ColumnTransformer` (xem `src/common.py`) và được fit **chỉ trên tập train** khi đặt trong Pipeline."),
code("prep = make_preprocessor().fit(X_train)\nXt = prep.transform(X_train)\nprint('Số cột sau mã hóa:', Xt.shape[1])\nprint('Trung bình cột số (train, sau chuẩn hóa):', np.round(Xt[:, :6].mean(0), 2))\nprint('Độ lệch chuẩn:', np.round(Xt[:, :6].std(0), 2))"),
])

