# ---------------- 03 modeling ----------------
save("03_modeling.ipynb", [
md("# 03. Xây dựng và đánh giá mô hình phân loại\nMục tiêu: dự đoán `HeartDisease`. Vì bỏ sót ca bệnh nguy hiểm hơn báo nhầm, **Recall của nhóm có bệnh** được ưu tiên (cùng F1 và ROC-AUC)."),
code(HEAD + "\nimport json, joblib\nfrom sklearn.model_selection import train_test_split, StratifiedKFold, cross_validate, GridSearchCV\nfrom sklearn.linear_model import LogisticRegression\nfrom sklearn.ensemble import RandomForestClassifier, GradientBoostingClassifier\nfrom sklearn.metrics import (accuracy_score, precision_score, recall_score, f1_score, roc_auc_score,\n                             confusion_matrix, ConfusionMatrixDisplay, RocCurveDisplay, make_scorer, fbeta_score)\nfrom sklearn.inspection import permutation_importance\ndf = load_clean(); X, y = df[FEATURES], df[TARGET]"),
md("## 1. Chia train/test\nTỷ lệ **80/20**, `stratify=y` để giữ tỷ lệ lớp ở cả hai tập, `random_state=42` để tái lập. Bộ dữ liệu chỉ ~300 dòng nên tập test chỉ ~61 mẫu: kết quả trên test dao động mạnh, vì vậy ta dùng thêm cross-validation 5 fold trên tập train làm bằng chứng chính."),
code("X_train, X_test, y_train, y_test = train_test_split(X, y, test_size=0.2, stratify=y, random_state=RANDOM_STATE)\nprint(X_train.shape, X_test.shape, '| tỷ lệ có bệnh train/test:', round(y_train.mean(), 3), round(y_test.mean(), 3))"),
md("## 2. Huấn luyện ba mô hình\nLogistic Regression (baseline, `class_weight='balanced'`), Random Forest, Gradient Boosting. Mỗi mô hình nằm trong `Pipeline` cùng bộ tiền xử lý để scaler/imputer chỉ fit trên train."),
code("def pipe(clf): return Pipeline([('prep', make_preprocessor()), ('clf', clf)])\nmodels = {\n 'Logistic Regression': pipe(LogisticRegression(max_iter=2000, class_weight='balanced')),\n 'Random Forest': pipe(RandomForestClassifier(n_estimators=300, class_weight='balanced', random_state=RANDOM_STATE)),\n 'Gradient Boosting': pipe(GradientBoostingClassifier(random_state=RANDOM_STATE)),\n}\nfor m in models.values(): m.fit(X_train, y_train)\ndef metrics(m, Xa, ya):\n    p = m.predict(Xa); pr = m.predict_proba(Xa)[:, 1]\n    return dict(Accuracy=accuracy_score(ya, p), Precision=precision_score(ya, p), Recall=recall_score(ya, p), F1=f1_score(ya, p), ROC_AUC=roc_auc_score(ya, pr))\ntrain_tab = pd.DataFrame({k: metrics(m, X_train, y_train) for k, m in models.items()}).T.round(3)\ntest_tab = pd.DataFrame({k: metrics(m, X_test, y_test) for k, m in models.items()}).T.round(3)\nprint('TRAIN'); display(train_tab); print('TEST'); display(test_tab)"),
md("## 3. Đánh giá bằng cross-validation (5 fold, trên tập train)"),
code("skf = StratifiedKFold(5, shuffle=True, random_state=RANDOM_STATE)\nsc = {'accuracy': 'accuracy', 'precision': 'precision', 'recall': 'recall', 'f1': 'f1', 'roc_auc': 'roc_auc'}\ncv_rows = {}\nfor k, m in models.items():\n    s = cross_validate(m, X_train, y_train, cv=skf, scoring=sc, n_jobs=-1)\n    cv_rows[k] = {f'{n} (TB)': s['test_'+n].mean() for n in sc} | {'Recall (độ lệch chuẩn)': s['test_recall'].std()}\ncv_tab = pd.DataFrame(cv_rows).T.round(3); cv_tab"),
code("(test_tab.join(cv_tab[['recall (TB)', 'roc_auc (TB)']].rename(columns={'recall (TB)': 'CV Recall', 'roc_auc (TB)': 'CV ROC-AUC'}))).to_csv(ROOT / 'report' / 'bang_so_sanh_3_mo_hinh.csv')\nfig, ax = plt.subplots(1, 3, figsize=(13, 3.9))\nfor a, (k, m) in zip(ax, models.items()):\n    ConfusionMatrixDisplay.from_estimator(m, X_test, y_test, display_labels=['Không bệnh', 'Có bệnh'], cmap='Blues', colorbar=False, ax=a)\n    a.set_title(k); a.grid(False)\nplt.suptitle('Hình 4.1. Confusion Matrix trên tập test', y=1.03)\nsavefig('fig_4_1_confusion_matrix')\nfig, ax = plt.subplots(figsize=(5.5, 4.5))\nfor k, m in models.items(): RocCurveDisplay.from_estimator(m, X_test, y_test, name=k, ax=ax)\nax.plot([0, 1], [0, 1], 'k--', lw=1); ax.set_title('Hình 4.2. Đường ROC trên tập test')\nsavefig('fig_4_2_roc')"),
md("## 4. Tinh chỉnh siêu tham số\n`GridSearchCV` 5 fold cho từng mô hình, chọn theo **F2** (đặt trọng số Recall gấp đôi Precision), phù hợp mục tiêu ưu tiên không bỏ sót ca bệnh. Lưới tham số giữ nhỏ vì dữ liệu ít, tránh overfit vào CV."),
code("f2 = make_scorer(fbeta_score, beta=2)\ngrids = {\n 'Logistic Regression': {'clf__C': [0.01, 0.1, 1, 10], 'clf__penalty': ['l2']},\n 'Random Forest': {'clf__n_estimators': [200, 400], 'clf__max_depth': [3, 5, 8, None], 'clf__min_samples_leaf': [1, 3, 5]},\n 'Gradient Boosting': {'clf__n_estimators': [100, 200], 'clf__learning_rate': [0.03, 0.1], 'clf__max_depth': [2, 3]},\n}\ntuned, rows = {}, []\nfor k, m in models.items():\n    gs = GridSearchCV(m, grids[k], scoring={'f2': f2, 'recall': 'recall', 'roc_auc': 'roc_auc'}, refit='f2', cv=skf, n_jobs=-1).fit(X_train, y_train)\n    tuned[k] = gs.best_estimator_\n    i = gs.best_index_\n    rows.append({'Mô hình': k, 'Tham số tốt nhất': {a.replace('clf__', ''): b for a, b in gs.best_params_.items()},\n                 'CV F2': round(gs.cv_results_['mean_test_f2'][i], 3), 'CV Recall': round(gs.cv_results_['mean_test_recall'][i], 3), 'CV ROC-AUC': round(gs.cv_results_['mean_test_roc_auc'][i], 3)})\nbest_tab = pd.DataFrame(rows); best_tab.to_csv(ROOT / 'report' / 'bang_tham_so_tot_nhat.csv', index=False); best_tab"),
code("tuned_test = pd.DataFrame({k: metrics(m, X_test, y_test) for k, m in tuned.items()}).T.round(3)\ntuned_test.to_csv(ROOT / 'report' / 'bang_test_sau_tinh_chinh.csv'); tuned_test"),
md("## 5. Chọn mô hình cuối\nTiêu chí: **CV F2** cao nhất (có xét Recall và ROC-AUC). Không chọn theo kết quả test để tránh \"nhìn trộm\" tập test."),
code("final_name = best_tab.sort_values(['CV F2', 'CV ROC-AUC'], ascending=False).iloc[0]['Mô hình']\nfinal = tuned[final_name]\nprint('Mô hình được chọn:', final_name)\nprint(classification_report(y_test, final.predict(X_test), target_names=['Không bệnh', 'Có bệnh'])) if 'classification_report' in globals() else None\nfrom sklearn.metrics import classification_report\nprint(classification_report(y_test, final.predict(X_test), target_names=['Không bệnh', 'Có bệnh']))\nprint(confusion_matrix(y_test, final.predict(X_test)))"),
md("## 6. Feature Importance\nDùng **permutation importance** trên tập test của pipeline cuối (đo mức giảm F2 khi xáo trộn một đặc trưng gốc), kết hợp độ quan trọng nội tại của Random Forest để đối chiếu."),
code("pi = permutation_importance(final, X_test, y_test, scoring=f2, n_repeats=30, random_state=RANDOM_STATE, n_jobs=-1)\nimp = pd.DataFrame({'Đặc trưng': FEATURES, 'Mức giảm F2': pi.importances_mean, 'Độ lệch chuẩn': pi.importances_std}).sort_values('Mức giảm F2', ascending=False)\nimp['Tên'] = imp['Đặc trưng'].map(VN)\nfig, ax = plt.subplots(figsize=(7, 5))\nsns.barplot(data=imp, y='Tên', x='Mức giảm F2', color='#457b9d', ax=ax)\nax.set_title(f'Hình 4.3. Permutation importance ({final_name})'); ax.set_ylabel('')\nsavefig('fig_4_3_feature_importance')\nimp.to_csv(ROOT / 'report' / 'bang_feature_importance.csv', index=False); imp.round(4)"),
code("rf = tuned['Random Forest']\nnames = rf.named_steps['prep'].get_feature_names_out()\nrf_imp = pd.Series(rf.named_steps['clf'].feature_importances_, index=names).sort_values(ascending=False).head(10)\nfig, ax = plt.subplots(figsize=(7, 4))\nrf_imp[::-1].plot.barh(color='#2a9d8f', ax=ax); ax.set_title('Hình 4.4. Độ quan trọng nội tại, Random Forest (top 10)')\nsavefig('fig_4_4_rf_importance'); rf_imp.round(3)"),
md("## 7. Lưu mô hình và kiểm tra nạp lại"),
code("meta = {'model': final_name, 'features': FEATURES, 'target': TARGET, 'random_state': RANDOM_STATE,\n        'test_metrics': {k: round(float(v), 4) for k, v in metrics(final, X_test, y_test).items()},\n        'feature_ranges': {c: [float(df[c].min()), float(df[c].max())] for c in NUMERIC}}\njoblib.dump(final, MODELS / 'model.joblib'); json.dump(meta, open(MODELS / 'model_meta.json', 'w', encoding='utf-8'), ensure_ascii=False, indent=2)\nreloaded = joblib.load(MODELS / 'model.joblib')\nassert np.allclose(reloaded.predict_proba(X_test), final.predict_proba(X_test)), 'Kết quả sau khi nạp lại khác'\nprint('Nạp lại model.joblib cho kết quả y hệt. Kích thước file (KB):', round((MODELS / 'model.joblib').stat().st_size/1024, 1))\nmeta['test_metrics']"),
])

# ---------------- 04 optimization ----------------
save("04_optimization.ipynb", [
md("# 04. Tối ưu hóa nâng cao\nNăm cải tiến so với notebook 03:\n1. **Đánh giá chắc hơn:** cross-validation lặp 5 fold x 5 lần trên toàn bộ 302 bệnh nhân (25 lần chia) thay vì một lần chia train/test 61 mẫu.\n2. **Chọn ngưỡng quyết định** theo mục tiêu Recall, đánh giá bằng **nested CV** để không lạc quan giả.\n3. **Hiệu chuẩn xác suất:** kiểm tra độ tin cậy của xác suất.\n4. **Khoảng tin cậy bootstrap** và **kiểm tra theo giới tính**.\n5. **Giải thích mô hình** (đóng góp từng đặc trưng) và huấn luyện lại mô hình cuối trên toàn bộ dữ liệu."),
code(HEAD + "\nimport json, joblib\nfrom sklearn.model_selection import RepeatedStratifiedKFold, StratifiedKFold, cross_validate, cross_val_predict, train_test_split\nfrom sklearn.linear_model import LogisticRegression\nfrom sklearn.ensemble import RandomForestClassifier, HistGradientBoostingClassifier, VotingClassifier\nfrom sklearn.svm import SVC\nfrom sklearn.calibration import calibration_curve\nfrom sklearn.metrics import (make_scorer, fbeta_score, recall_score, precision_score, f1_score, roc_auc_score, brier_score_loss)\ndf = load_clean(); X, y = df[FEATURES], df[TARGET]\nP = lambda c: Pipeline([('prep', make_preprocessor()), ('clf', c)])\nLR = lambda: LogisticRegression(C=0.1, max_iter=3000, class_weight='balanced')\nRF = lambda: RandomForestClassifier(n_estimators=300, max_depth=3, min_samples_leaf=3, class_weight='balanced', random_state=RANDOM_STATE)\nHGB = lambda: HistGradientBoostingClassifier(max_depth=2, learning_rate=0.05, max_iter=150, l2_regularization=1.0, random_state=RANDOM_STATE)"),
md("## 1. So sánh mô hình bằng cross-validation lặp (5 x 5 trên 302 mẫu)\nThêm HistGradientBoosting, SVM (RBF) và một ensemble bỏ phiếu mềm (LR + RF + HGB). Siêu tham số lấy từ bước tinh chỉnh ở notebook 03 hoặc đặt bảo thủ cho dữ liệu nhỏ. Báo cáo **trung bình ± độ lệch chuẩn qua 25 lần chia**."),
code("models = {'Logistic Regression': P(LR()), 'Random Forest': P(RF()), 'HistGradientBoosting': P(HGB()),\n          'SVM (RBF)': P(SVC(C=1, kernel='rbf', probability=True, class_weight='balanced', random_state=RANDOM_STATE)),\n          'Ensemble (LR+RF+HGB)': P(VotingClassifier([('lr', LR()), ('rf', RF()), ('hgb', HGB())], voting='soft'))}\ncv = RepeatedStratifiedKFold(n_splits=5, n_repeats=5, random_state=RANDOM_STATE)\nsc = {'recall': 'recall', 'precision': 'precision', 'f1': 'f1', 'f2': make_scorer(fbeta_score, beta=2), 'roc_auc': 'roc_auc', 'pr_auc': 'average_precision', 'brier': 'neg_brier_score'}\nraw, rows = {}, []\nfor k, m in models.items():\n    s = cross_validate(m, X, y, cv=cv, scoring=sc, n_jobs=-1); raw[k] = s\n    rows.append({'Mô hình': k, **{n: f\"{(-1 if n=='brier' else 1)*s['test_'+n].mean():.3f} ± {s['test_'+n].std():.3f}\" for n in sc}})\ncmp_tab = pd.DataFrame(rows).rename(columns={'brier': 'Brier (thấp hơn tốt hơn)'}); cmp_tab.to_csv(ROOT / 'report' / 'bang_so_sanh_cv_lap.csv', index=False); cmp_tab"),
code("fig, ax = plt.subplots(1, 3, figsize=(14, 4))\nfor a, (n, t) in zip(ax, [('f2', 'F2'), ('recall', 'Recall'), ('roc_auc', 'ROC-AUC')]):\n    mu = [raw[k]['test_'+n].mean() for k in models]; sd = [raw[k]['test_'+n].std() for k in models]\n    a.barh(list(models)[::-1], mu[::-1], xerr=sd[::-1], color='#457b9d', capsize=4); a.set_xlim(0.6, 1.0); a.set_title(t)\nplt.suptitle('Hình 4.5. So sánh mô hình, CV 5x5 (thanh sai số = độ lệch chuẩn qua 25 lần chia)', y=1.03)\nsavefig('fig_4_5_so_sanh_cv_lap')"),
md("**Đọc kết quả:** độ lệch chuẩn giữa các lần chia (khoảng 0,06 đến 0,09) **lớn hơn nhiều** chênh lệch giữa các mô hình. Nghĩa là năm mô hình về cơ bản **hòa nhau**. Khi hòa, nguyên tắc tiết kiệm (Occam) và yêu cầu giải thích được trong y tế dẫn tới chọn **Logistic Regression**: đơn giản nhất, Precision và Brier tốt nhất trong nhóm, hệ số giải thích được từng ca."),
md("## 2. Chọn ngưỡng quyết định theo mục tiêu Recall (nested CV)\nNgưỡng 0,5 mặc định không gắn với mục tiêu y tế. Ta thử ba quy tắc, chọn ngưỡng **chỉ từ dữ liệu train của từng fold** (bằng dự đoán out-of-fold bên trong), rồi áp dụng lên fold test. Nhờ vậy ước lượng không bị lạc quan do chọn ngưỡng trên chính dữ liệu đánh giá."),
code("GRID = np.round(np.arange(0.15, 0.80, 0.025), 3)\ndef oof_proba(Xa, ya, seed=0):\n    return cross_val_predict(P(LR()), Xa, ya, cv=StratifiedKFold(5, shuffle=True, random_state=seed), method='predict_proba')[:, 1]\ndef thr_f2(oof, ya):\n    s = np.array([fbeta_score(ya, oof >= t, beta=2) for t in GRID]); return GRID[int(np.argmax(np.convolve(s, np.ones(3)/3, mode='same')))]\ndef thr_recall(oof, ya, target=0.90):\n    ok = [t for t in GRID if recall_score(ya, oof >= t) >= target]; return max(ok) if ok else GRID[0]\nrules = {'Ngưỡng 0,5 (mặc định)': lambda o, a: 0.5, 'Tối đa hóa F2': thr_f2, 'Recall >= 0,90 (Precision cao nhất)': thr_recall}\nout = {k: [] for k in rules}; chosen = {k: [] for k in rules}\nfor tr, te in cv.split(X, y):\n    Xa, ya, Xb, yb = X.iloc[tr], y.iloc[tr], X.iloc[te], y.iloc[te]\n    p = P(LR()).fit(Xa, ya).predict_proba(Xb)[:, 1]; oo = oof_proba(Xa, ya)\n    for k, f in rules.items():\n        t = f(oo, ya); chosen[k].append(t); pr = p >= t\n        out[k].append((recall_score(yb, pr), precision_score(yb, pr), f1_score(yb, pr), fbeta_score(yb, pr, beta=2)))\nthr_tab = pd.DataFrame({k: dict(zip(['Recall', 'Precision', 'F1', 'F2'], np.array(v).mean(0))) | {'Ngưỡng TB': np.mean(chosen[k]), 'Recall (độ lệch chuẩn)': np.array(v)[:, 0].std()} for k, v in out.items()}).T.round(3)\nthr_tab.to_csv(ROOT / 'report' / 'bang_nested_nguong.csv'); thr_tab"),
md("Đây là **đánh đổi chính sách**, không phải có đáp án đúng duy nhất: hạ ngưỡng làm Recall tăng nhưng Precision giảm (nhiều người khỏe bị báo nhầm). Bài chọn quy tắc **Recall >= 0,90** làm chế độ sàng lọc vì dễ phát biểu và dễ giải thích hơn việc tối đa hóa F2."),
code("oof_all = np.mean([oof_proba(X, y, seed=s) for s in range(5)], axis=0)\nts = np.arange(0.1, 0.9, 0.01)\nrc = [recall_score(y, oof_all >= t) for t in ts]; pc = [precision_score(y, oof_all >= t) for t in ts]\nT_FINAL = float(thr_recall(oof_all, y)); print('Ngưỡng sàng lọc (Recall >= 0,90 trên dự đoán out-of-fold toàn bộ dữ liệu):', T_FINAL)\nfig, ax = plt.subplots(figsize=(6.5, 4.2))\nax.plot(ts, rc, label='Recall', color='#e76f51'); ax.plot(ts, pc, label='Precision', color='#457b9d')\nax.axvline(0.5, ls=':', color='gray'); ax.axvline(T_FINAL, ls='--', color='#2a9d8f', label=f'Ngưỡng sàng lọc = {T_FINAL:.2f}')\nax.set_xlabel('Ngưỡng quyết định'); ax.set_ylabel('Giá trị'); ax.set_title('Hình 4.6. Đánh đổi Recall và Precision theo ngưỡng'); ax.legend()\nsavefig('fig_4_6_danh_doi_nguong')"),
md("## 3. Hiệu chuẩn xác suất\nỨng dụng hiển thị xác suất (%), nên cần kiểm tra xác suất có đáng tin không: trong số người được dự đoán 30% thì có khoảng 30% thật sự mắc bệnh hay không."),
code("fp, mp = calibration_curve(y, oof_all, n_bins=6, strategy='quantile')\nfig, ax = plt.subplots(figsize=(5, 4.5))\nax.plot([0, 1], [0, 1], 'k--', lw=1, label='Hiệu chuẩn hoàn hảo'); ax.plot(mp, fp, 'o-', color='#e76f51', label='Logistic Regression (out-of-fold)')\nax.set_xlabel('Xác suất dự đoán trung bình'); ax.set_ylabel('Tỷ lệ có bệnh thực tế'); ax.set_title('Hình 4.7. Biểu đồ hiệu chuẩn'); ax.legend()\nsavefig('fig_4_7_hieu_chuan')\nbr = brier_score_loss(y, oof_all); base = brier_score_loss(y, np.full(len(y), y.mean()))\nprint(f'Brier = {br:.3f} (mô hình luôn đoán tỷ lệ nền: {base:.3f})')\nprint(pd.DataFrame({'Dự đoán TB': mp.round(3), 'Thực tế': fp.round(3)}))"),
md("## 4. Kiểm tra trên tập test giữ riêng, khoảng tin cậy và nhóm giới tính\nChia 80/20 như notebook 03 (cùng `random_state`). Ngưỡng chọn chỉ từ train. Tập test chỉ dùng **một lần**."),
code("Xtr, Xte, ytr, yte = train_test_split(X, y, test_size=0.2, stratify=y, random_state=RANDOM_STATE)\nm = P(LR()).fit(Xtr, ytr); p = m.predict_proba(Xte)[:, 1]\nt_tr = float(thr_recall(oof_proba(Xtr, ytr), ytr)); print('Ngưỡng chọn chỉ từ train:', t_tr)\nrng = np.random.default_rng(RANDOM_STATE); yt = yte.values\ndef boot(f, n=2000):\n    v = []\n    for _ in range(n):\n        i = rng.integers(0, len(yt), len(yt))\n        if len(set(yt[i])) < 2: continue\n        v.append(f(yt[i], p[i]))\n    return np.percentile(v, [2.5, 97.5])\nrows = []\nfor name, t in [('Ngưỡng 0,5', 0.5), (f'Ngưỡng sàng lọc {t_tr:.2f}', t_tr)]:\n    pr = p >= t; ci = boot(lambda a, b: recall_score(a, b >= t))\n    rows.append({'Chế độ': name, 'Recall': recall_score(yt, pr), 'KTC 95% Recall': f'{ci[0]:.2f} đến {ci[1]:.2f}', 'Precision': precision_score(yt, pr), 'Bỏ sót (FN)': int(((~pr) & (yt == 1)).sum()), 'Báo nhầm (FP)': int((pr & (yt == 0)).sum())})\nauc_ci = boot(lambda a, b: roc_auc_score(a, b))\nres_tab = pd.DataFrame(rows).round(3); res_tab.to_csv(ROOT / 'report' / 'bang_test_v2.csv', index=False); display(res_tab)\nprint(f'ROC-AUC test = {roc_auc_score(yt, p):.3f}, KTC 95% bootstrap = {auc_ci[0]:.2f} đến {auc_ci[1]:.2f}')"),
code("sx = []\nfor s_, nm in [(0, 'Nữ'), (1, 'Nam')]:\n    k = Xte['sex'].values == s_; pr = p[k] >= t_tr\n    sx.append({'Nhóm': nm, 'n test': int(k.sum()), 'Số ca bệnh': int(yt[k].sum()), 'Recall': recall_score(yt[k], pr), 'ROC-AUC': roc_auc_score(yt[k], p[k])})\npd.DataFrame(sx).round(3)"),
md("Số ca bệnh ở nhóm nữ trong tập test rất ít (vài ca), nên kết quả theo giới **chỉ mang tính tham khảo** và không đủ để kết luận mô hình công bằng hay thiên lệch giữa hai giới. Cần dữ liệu lớn hơn để kiểm tra nghiêm túc."),
md("## 5. Giải thích mô hình\nLogistic Regression cho phép tách đóng góp của từng đặc trưng vào log-odds: `hệ số x (giá trị - giá trị trung bình)`. Với mô hình tuyến tính, đây chính là giá trị SHAP (giả định các đặc trưng độc lập). Biến One-Hot của cùng một đặc trưng gốc được cộng lại."),
code("final = P(LR()).fit(X, y)   # huấn luyện lại trên toàn bộ 302 mẫu cho bản triển khai\nnames = list(final.named_steps['prep'].get_feature_names_out()); coef = final.named_steps['clf'].coef_[0]\nref = final.named_steps['prep'].transform(X).mean(axis=0)\ndef orig(n):\n    kind, rest = n.split('__', 1); return rest.rsplit('_', 1)[0] if kind == 'cat' else rest\ng = pd.DataFrame({'feat': [orig(n) for n in names], 'coef': coef}); gi = g.assign(a=g.coef.abs()).groupby('feat').a.sum().sort_values()\nfig, ax = plt.subplots(figsize=(6.5, 4.5)); ax.barh([VN[f] for f in gi.index], gi.values, color='#457b9d')\nax.set_xlabel('Tổng |hệ số| (dữ liệu đã chuẩn hóa)'); ax.set_title('Hình 4.8. Mức ảnh hưởng của từng đặc trưng (Logistic Regression)')\nsavefig('fig_4_8_he_so_logistic'); gi.sort_values(ascending=False).round(2)"),
md("## 6. Lưu mô hình cuối (huấn luyện trên toàn bộ dữ liệu) và siêu dữ liệu"),
code("meta = {'model': 'Logistic Regression (C=0.1, class_weight=balanced)', 'features': FEATURES, 'trained_on': int(len(X)),\n        'threshold_screening': T_FINAL, 'threshold_high': 0.60, 'threshold_default': 0.5,\n        'transformed_names': names, 'ref_means': [float(v) for v in ref],\n        'cv5x5_metrics': {k: round(float(raw['Logistic Regression']['test_'+k].mean()) * (-1 if k == 'brier' else 1), 4) for k in sc},\n        'nested_threshold_metrics': thr_tab.loc['Recall >= 0,90 (Precision cao nhất)'].to_dict(),\n        'note': 'Số liệu đánh giá lấy từ nested CV/test giữ riêng; mô hình lưu là bản huấn luyện lại trên toàn bộ dữ liệu.'}\njoblib.dump(final, MODELS / 'model_final.joblib'); json.dump(meta, open(MODELS / 'model_final_meta.json', 'w', encoding='utf-8'), ensure_ascii=False, indent=2)\nassert np.allclose(joblib.load(MODELS / 'model_final.joblib').predict_proba(X), final.predict_proba(X))\nprint('Đã lưu models/model_final.joblib | ngưỡng sàng lọc =', T_FINAL)"),
])
